import type { HTMLArkProps } from '@ark-ui/react/factory';
import { ark } from '@ark-ui/react/factory';
import { clsx } from 'clsx';
import type { ForwardedRef } from 'react';
import { forwardRef } from 'react';
import styles from './List.module.css';

type ListElement = 'ul' | 'ol';
type ListMarker = 'disc' | 'decimal' | 'none';
type ListGap = 'xs' | 'sm' | 'md' | 'lg' | 'xl' | '2xl';
type ListSize = 'xs' | 'sm' | 'md' | 'lg' | 'xl';
type ListTone = 'default' | 'muted' | 'subtle' | 'primary' | 'destructive';

type ListRootProps = HTMLArkProps<'ol'> & {
  as?: ListElement;
  marker?: ListMarker;
  gap?: ListGap;
  size?: ListSize;
  tone?: ListTone;
};

const List = forwardRef<HTMLUListElement | HTMLOListElement, ListRootProps>(function List(
  {
    as = 'ul',
    marker = as === 'ol' ? 'decimal' : 'disc',
    gap = 'sm',
    size = 'md',
    tone = 'default',
    role = marker === 'none' ? 'list' : undefined,
    className,
    ...props
  },
  ref,
) {
  const Element = ark[as] as typeof ark.ol;

  return (
    <Element
      {...props}
      ref={ref as ForwardedRef<HTMLOListElement>}
      role={role}
      data-scope="list"
      data-part="root"
      data-slot="list-root"
      data-gap={gap}
      data-marker={marker}
      data-size={size}
      data-tone={tone}
      className={clsx(styles.root, className)}
    />
  );
});

const ListItem = forwardRef<HTMLLIElement, HTMLArkProps<'li'>>(function ListItem(props, ref) {
  return <ark.li {...props} ref={ref} data-scope="list" data-part="item" data-slot="list-item" />;
});

const ListIndicator = forwardRef<HTMLSpanElement, HTMLArkProps<'span'>>(function ListIndicator(
  { className, ...props },
  ref,
) {
  return (
    <ark.span
      {...props}
      ref={ref}
      data-scope="list"
      data-part="indicator"
      data-slot="list-indicator"
      className={clsx(styles.indicator, className)}
    />
  );
});

export { List, ListIndicator, ListItem };
export type { ListElement, ListGap, ListMarker, ListRootProps, ListSize, ListTone };

@layer moduix.components {
  .root {
    --_list-gap: var(--moduix-spacing-2);

    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    gap: var(--_list-gap);
    margin: 0;
    padding: 0;
    padding-inline-start: var(--moduix-spacing-5);
    color: var(--moduix-color-foreground);
    font-size: var(--moduix-text-md);
    font-weight: var(--moduix-weight-regular);
    line-height: var(--moduix-line-height-text-md);
    letter-spacing: 0;
    list-style-type: disc;
    overflow-wrap: break-word;

    &[data-marker='decimal'] {
      list-style-type: decimal;
    }

    &[data-marker='none'] {
      padding-inline-start: 0;
      list-style: none;
    }

    &[data-gap='xs'] {
      --_list-gap: var(--moduix-spacing-1);
    }

    &[data-gap='md'] {
      --_list-gap: var(--moduix-spacing-3);
    }

    &[data-gap='lg'] {
      --_list-gap: var(--moduix-spacing-4);
    }

    &[data-gap='xl'] {
      --_list-gap: var(--moduix-spacing-5);
    }

    &[data-gap='2xl'] {
      --_list-gap: var(--moduix-spacing-6);
    }

    & > li > :is(ul, ol) {
      margin-block-start: var(--_list-gap);
    }

    & > li:has(> .indicator) {
      display: flex;
      align-items: flex-start;
    }

    &[data-size='xs'] {
      font-size: var(--moduix-text-xs);
      line-height: var(--moduix-line-height-text-xs);
    }

    &[data-size='sm'] {
      font-size: var(--moduix-text-sm);
      line-height: var(--moduix-line-height-text-sm);
    }

    &[data-size='lg'] {
      font-size: var(--moduix-text-lg);
      line-height: var(--moduix-line-height-text-lg);
    }

    &[data-size='xl'] {
      font-size: var(--moduix-text-xl);
      line-height: var(--moduix-line-height-text-xl);
    }

    &[data-tone='muted'] {
      color: var(--moduix-color-muted-foreground);
    }

    &[data-tone='subtle'] {
      color: var(--moduix-color-secondary-foreground);
    }

    &[data-tone='primary'] {
      color: var(--moduix-color-primary);
    }

    &[data-tone='destructive'] {
      color: var(--moduix-color-destructive);
    }
  }

  .indicator {
    display: inline-flex;
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
    min-height: 1lh;
    margin-inline-end: var(--moduix-spacing-2);

    & > :where(svg) {
      width: 1em;
      height: 1em;
      flex-shrink: 0;
      pointer-events: none;
    }
  }
}
